/** Convert 1-2 uppercase letters into a column number (A=1, Z=26, AA=27, ZZ=702). */
export function colToNum(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** Convert a column number back into letters. */
export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const r = (n - 1) % 26
    s = String.fromCharCode(65 + r) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

const ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Validate a token as an address: one or two letters, one to three digits,
 * row at least 1. Returns { col, row, key } or null when out of range.
 */
export function parseAddressStrict(raw) {
  const m = ADDR_RE.exec(raw)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const colLetters = m[1].toUpperCase()
  const col = colToNum(colLetters)
  const key = colLetters + String(row)
  return { col, row, key }
}

/** Compare two {col,row} style keys/records for ascending column then row order. */
export function compareAddr(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

