      i++
      continue
    }
    if (isDigit(c)) {
      let j = i + 1
      while (j < n && isDigit(s[j])) j++
      if (s[j] === '.' && isDigit(s[j + 1] || '')) {
        j++
        while (j < n && isDigit(s[j])) j++
      }
      toks.push({ type: 'NUM', value: s.slice(i, j) })
      i = j
      continue
    }
    if (isAlpha(c)) {
      let j = i + 1
      while (j < n && isAlnum(s[j])) j++
      toks.push({ type: 'IDENT', value: s.slice(i, j) })
      i = j
      continue
    }
    if (c === '(') {
      toks.push({ type: 'LP' })
      i++
      continue
    }
    if (c === ')') {
      toks.push({ type: 'RP' })
      i++
      continue
    }
    if (c === ',') {
      toks.push({ type: 'COMMA' })
      i++
      continue
    }
    if (c === ':') {
      toks.push({ type: 'COLON' })
      i++
      continue
    }
    if (c === '<') {
      if (s[i + 1] === '=') {
        toks.push({ type: 'OP', value: '<=' })
        i += 2
      } else if (s[i + 1] === '>') {
        toks.push({ type: 'OP', value: '<>' })
        i += 2
      } else {
        toks.push({ type: 'OP', value: '<' })
        i++
      }
      continue
    }
    if (c === '>') {
      if (s[i + 1] === '=') {
        toks.push({ type: 'OP', value: '>=' })
        i += 2
      } else {
        toks.push({ type: 'OP', value: '>' })
        i++
      }
      continue
