{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-bCbpPd/src/parser.js","content":"// Recursive-descent parser for formula bodies, producing an AST.
//
// Precedence, loosest to tightest: comparisons; + -; * /; ^ (right-assoc);
// leading unary + or - (binds tighter than ^).
//
// A range (`A1:B3`) is only accepted directly as a function call argument.

import { tokenize, LexError } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Parser {
  constructor(tokens) {
    this.toks = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.toks[this.pos + offset]
  }

  next() {
    return this.toks[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (t.type !== type) throw new ParseError(`expected ${type}, got ${t.type}`)
    return t
  }

  parseFormula() {
    const expr = this.parseExpr()
    this.expect('EOF')
    return expr
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    for (;;) {
      const t = this.peek()
      if (t.type === 'OP' && COMPARISON_OPS.has(t.value)) {
        this.next()
        const right = this.parseAdditive()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    for (;;) {
      const t = this.peek()
      if (t.type === 'OP' && (t.value === '+' || t.value === '-')) {
        this.next()
        const right = this.parseMultiplicative()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    for (;;) {
      const t = this.peek()
      if (t.type === 'OP' && (t.value === '*' || t.value === '/')) {
        this.next()
        const right = this.parsePower()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    const t = this.peek()
    if (t.type === 'OP' && t.value === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    const t = this.peek()
    if (t.type === 'OP' && (t.value === '+' || t.value === '-')) {
      this.next()
      const operand = this.parseUnary()
      return { type: 'unary', op: t.value, operand }
    }
    return this.parsePrimary()
  }

  // Whether the token at `offset` looks like an address-shaped identifier
  // (not TRUE/FALSE). Shape validity (in-range or not) is checked later.
  isAddressIdent(t) {
    if (t.type !== 'IDENT') return false
    const u = t.value.toUpperCase()
    return u !== 'TRUE' && u !== 'FALSE'
  }

  // Parse one function-call argument: either a direct range (addr:addr) or a
  // full expression.
  parseArgument() {
    const t0 = this.peek()
    const t1 = this.peek(1)
    const t2 = this.peek(2)
    if (this.isAddressIdent(t0) && t1.type === 'COLON' && this.isAddressIdent(t2)) {
      this.next()
      this.next()
      this.next()
      return { type: 'range', a: t0.value, b: t2.value }
    }
    return this.parseExpr()
  }

  parsePrimary() {
    const t = this.peek()
    if (t.type === 'NUM') {
      this.next()
      return { type: 'num', raw: t.value }
    }
    if (t.type === 'LP') {
      this.next()
      const e = this.parseExpr()
      this.expect('RP')
      return e
    }
    if (t.type === 'IDENT') {
      const u = t.value.toUpperCase()
      if (u === 'TRUE' || u === 'FALSE') {
        this.next()
        return { type: 'bool', value: u === 'TRUE' }
      }
      if (this.peek(1).type === 'LP') {
        this.next() // ident
        this.next() // LP
        const args = []
        if (this.peek().type !== 'RP') {
          for (;;) {
            args.push(this.parseArgument())
            if (this.peek().type === 'COMMA') {
              this.next()
              continue
            }
            break
          }
        }
        this.expect('RP')
        return { type: 'call', name: u, args }
      }
      this.next()
      return { type: 'address', raw: t.value }
    }
    throw new ParseError(`unexpected token ${t.type}`)
  }
}

/**
 * Parse a formula body (the text after the leading '='). Returns
 * { ok: true, ast } on success, or { ok: false } if the grammar rejects it.
 */
export function parseFormula(body) {
  try {
    const toks = tokenize(body)
    const parser = new Parser(toks)
    const ast = parser.parseFormula()
    return { ok: true, ast }
  } catch (e) {
    if (e instanceof LexError || e instanceof ParseError) return { ok: false }
    throw e
  }
}
"}

