// comparison rules shared by literal evaluation and formula evaluation.

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const numVal = (v) => ({ t: 'num', v })
export const textVal = (v) => ({ t: 'text', v })
export const boolVal = (v) => ({ t: 'bool', v })
export const errVal = (v) => ({ t: 'err', v })

export const isError = (v) => v.t === 'err'

/** Read a value in an arithmetic position: number as-is, bool as 1/0, text is #VALUE!. */
export function toNumber(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return numVal(v.v ? 1 : 0)
  if (v.t === 'text') return errVal('#VALUE!')
  return v // error, passthrough
}

/** Read a value as an IF condition: TRUE/FALSE or a number's truthiness. */
export function toCondition(v) {
  if (v.t === 'bool') return v
  if (v.t === 'num') return boolVal(v.v !== 0)
  if (v.t === 'text') return errVal('#VALUE!')
  return v // error, passthrough
}

function typeRank(v) {
  if (v.t === 'num') return 0
  if (v.t === 'text') return 1
  return 2 // bool
}

/** Compare two non-error values per the cross-kind ordering rules. Returns -1/0/1. */
function compareValues(a, b) {
  if (a.t !== b.t) {
    const ra = typeRank(a)
    const rb = typeRank(b)
    return ra < rb ? -1 : 1
  }
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  // bool: false below true
  const av = a.v ? 1 : 0
  const bv = b.v ? 1 : 0
  return av < bv ? -1 : av > bv ? 1 : 0
}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
export function isComparisonOp(op) {
  return COMPARISON_OPS.has(op)
}

function applyComparison(op, cmp) {
  switch (op) {
    case '=':
      return boolVal(cmp === 0)
    case '<>':
      return boolVal(cmp !== 0)
    case '<':
      return boolVal(cmp < 0)
    case '<=':
      return boolVal(cmp <= 0)
    case '>':
      return boolVal(cmp > 0)
    case '>=':
      return boolVal(cmp >= 0)
  }
  throw new Error(`unknown comparison op ${op}`)
}

/** Apply a binary operator to two already-evaluated values. */
export function binOp(op, l, r) {
  if (isError(l)) return l
  if (isError(r)) return r
  if (isComparisonOp(op)) {
    return applyComparison(op, compareValues(l, r))
  }
  const ln = toNumber(l)
  if (isError(ln)) return ln
  const rn = toNumber(r)
  if (isError(rn)) return rn
  let res
  switch (op) {
    case '+':
      res = ln.v + rn.v
      break
    case '-':
      res = ln.v - rn.v
      break
    case '*':
      res = ln.v * rn.v
      break
    case '/':
      if (rn.v === 0) return errVal('#DIV/0!')
      res = ln.v / rn.v
      break
    case '^':
      res = Math.pow(ln.v, rn.v)
      break
    default:
      throw new Error(`unknown operator ${op}`)
  }
  if (!isFinite(res)) return errVal('#DIV/0!')
  return numVal(res)
}

/** Apply a unary +/- to an already-evaluated value. */
export function unaryOp(op, v) {
  if (isError(v)) return v
  const n = toNumber(v)
  if (isError(n)) return n
  const res = op === '-' ? -n.v : n.v
  if (!isFinite(res)) return errVal('#DIV/0!')
  return numVal(res)
}

function roundSignificant(n, sig) {
  if (n === 0) return 0
  return parseFloat(n.toPrecision(sig))
}

/** Format a number the way JavaScript would print it, after rounding to 10 sig figs. */
export function formatNumber(n) {
  if (Object.is(n, -0)) n = 0
  const rounded = roundSignificant(n, 10)
  return String(rounded)
}

/** Format any value for the `values` output. */
export function formatValue(v) {
  switch (v.t) {
    case 'num':
      return formatNumber(v.v)
    case 'text':
      return v.v
    case 'bool':
      return v.v ? 'TRUE' : 'FALSE'
    case 'err':
      return v.v
  }
  throw new Error(`unknown value type ${v.t}`)
}

/** Parse literal (non-formula) cell content into a value. */
export function parseLiteral(content) {
  if (content === '') return numVal(0)
  if (/^-?\d+(\.\d+)?$/.test(content)) return numVal(parseFloat(content))
  if (ERROR_TOKENS.includes(content)) return errVal(content)
  return textVal(content)
}
"}

