import { parseAddressStrict } from './address.js'

export class SheetError extends Error {
  constructor(kind, line, addr) {
    super(`${kind}: line ${line}: ${addr}`)
    this.kind = kind // 'invalid' or 'dup'
    this.line = line
    this.addr = addr
  }
}

/**
 * Returns a Map from canonical address key to
 * { content, col, row, line }.
 */
export function parseSheet(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const cells = new Map()

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const line = lines[idx]
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    let wsIdx = -1
    for (let k = 0; k < stripped.length; k++) {
      const c = stripped[k]
      if (c === ' ' || c === '\t') {
        wsIdx = k
        break
      }
    }

    let addrStr
    let rest
    if (wsIdx === -1) {
      addrStr = stripped
      rest = ''
    } else {
      addrStr = stripped.slice(0, wsIdx)
      let k = wsIdx
      while (k < stripped.length && (stripped[k] === ' ' || stripped[k] === '\t')) k++
      rest = stripped.slice(k)
    }

    const info = parseAddressStrict(addrStr)
    if (!info) {
      throw new SheetError('invalid', lineNo, addrStr)
    }
    if (cells.has(info.key)) {
      throw new SheetError('dup', lineNo, info.key)
    }
    cells.set(info.key, { content: rest, col: info.col, row: info.row, line: lineNo })
  }

  return cells
}
"}

