{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-bCbpPd/src/deps.js","content":"// Pure syntactic walk of a formula AST collecting the addresses it names.

import { parseAddressStrict, numToCol, compareAddr } from './address.js'

function addRangeAddresses(rawA, rawB, out) {
  const a = parseAddressStrict(rawA)
  const b = parseAddressStrict(rawB)
  if (!a || !b) return
  const colMin = Math.min(a.col, b.col)
  const colMax = Math.max(a.col, b.col)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  for (let col = colMin; col <= colMax; col++) {
    const letters = numToCol(col)
    for (let row = rowMin; row <= rowMax; row++) {
      out.set(letters + row, { col, row })
    }
  }
}

function walk(node, out) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'address': {
      const info = parseAddressStrict(node.raw)
      if (info) out.set(info.key, { col: info.col, row: info.row })
      return
    }
    case 'range':
      addRangeAddresses(node.a, node.b, out)
      return
    case 'unary':
      walk(node.operand, out)
      return
    case 'binop':
      walk(node.left, out)
      walk(node.right, out)
      return
    case 'call':
      for (const a of node.args) walk(a, out)
      return
  }
}

/** Returns a sorted array of canonical address keys named directly by the AST. */
export function collectDeps(ast) {
  const out = new Map() // key -> {col,row}
  walk(ast, out)
  const entries = [...out.entries()].map(([key, pos]) => ({ key, ...pos }))
  entries.sort(compareAddr)
  return entries.map((e) => e.key)
}
"}

