import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { parseFormula } from './parser.js'
import { collectDeps } from './deps.js'
import { Evaluator } from './evaluator.js'
import { formatValue } from './values.js'
import { numToCol } from './address.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
    return
  }
  const mode = argv[0]

  const input = fs.readFileSync(0, 'utf8')

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      if (e.kind === 'invalid') {
        fail(`error: line ${e.line}: invalid cell address ${e.addr}`)
      } else {
        fail(`error: line ${e.line}: cell ${e.addr} is declared twice`)
      }
      return
    }
    throw e
  }

  const entries = [...sheet.entries()].map(([key, info]) => ({ key, ...info }))
  entries.sort((a, b) => (a.col !== b.col ? a.col - b.col : a.row - b.row))

  const out = []

  if (mode === 'values') {
    const evaluator = new Evaluator(sheet)
    for (const e of entries) {
      const v = evaluator.evalCell(e.key)
      out.push(`${e.key}=${formatValue(v)}\n`)
    }
  } else {
    for (const e of entries) {
      let depsLine
      if (e.content.startsWith('=')) {
        const parsed = parseFormula(e.content.slice(1))
        if (parsed.ok) {
          const deps = collectDeps(parsed.ast)
          depsLine = deps.length ? ` ${deps.join(' ')}` : ''
        } else {
          depsLine = ''
        }
      } else {
        depsLine = ''
      }
      out.push(`${e.key}:${depsLine}\n`)
    }
  }

  process.stdout.write(out.join(''))
  process.exit(0)
}

main()
"}

